        public PlayerMurderEvent() { }
        public PlayerMurderEvent(PlayerControl killer, PlayerControl victim, PlayerState state = PlayerState.BeKilled) : base(killer) { Victim = victim; State = state; }
    }

    /// <summary>尝试击杀（可阻止）</summary>
    public class PlayerTryMurderEvent : BaseCancelablePlayerEvent
    {
        public PlayerControl Killer => Player;
