using System;
using System.Collections.Generic;
using LightInDark.Configuration;

namespace LightInDark.Roles
{
    /// <summary>
    /// 角色注册中心。在插件主类 Load() 中调用 RoleRegistry.Register() 注册角色。
    /// 防止运行时反射扫描的性能消耗。
    /// </summary>
    public static class RoleRegistry
    {
        private static readonly Dictionary<string, DefinedRole> _roles = new();
        private static readonly Dictionary<Type, DefinedRole> _rolesByType = new();
        private static readonly Dictionary<int, DefinedRole> _rolesById = new();
        private static int _nextId;

        /// <summary>已注册的所有角色定义</summary>
        public static IReadOnlyCollection<DefinedRole> AllRoles => _roles.Values;

        /// <summary>
        /// 注册角色。在 LIDPlugin.Load() 中调用。
        /// </summary>
        public static T Register<T>() where T : DefinedRole, new()
            => Register(new T());

        /// <summary>
        /// 注册角色实例。
        /// </summary>
        public static T Register<T>(T role) where T : DefinedRole
        {
            if (role == null) throw new ArgumentNullException(nameof(role));
            role.Id = _nextId++;
            _roles[role.Name] = role;
            _rolesByType[typeof(T)] = role;
            _rolesById[role.Id] = role;
            return role;
        }

        /// <summary>按名称获取角色定义</summary>
        public static DefinedRole GetByName(string name)
            => _roles.TryGetValue(name, out var role) ? role : null;

        /// <summary>按类型获取角色定义</summary>
        public static T Get<T>() where T : DefinedRole
            => _rolesByType.TryGetValue(typeof(T), out var role) ? role as T : null;

        /// <summary>按注册序号获取角色定义</summary>
        public static DefinedRole GetById(int id)
            => _rolesById.TryGetValue(id, out var role) ? role : null;

        /// <summary>角色是否已注册</summary>
        public static bool IsRegistered(string name) => _roles.ContainsKey(name);

        /// <summary>清空所有注册（游戏结束时调用）</summary>
        public static void Clear()
        {
            _roles.Clear();
            _rolesByType.Clear();
            _rolesById.Clear();
            _nextId = 0;
        }
    }

    /// <summary>
    /// 角色类型检查扩展。使用方式：player.Is&lt;SheriffRuntime&gt;()
    /// 或 player.HasRole&lt;SheriffRuntime&gt;()
    /// </summary>
    public static class RoleTypeChecker
    {
        /// <summary>检查玩家是否拥有指定类型的角色</summary>
        public static bool HasRole<T>(this Game.Player player) where T : RuntimeRole
            => player.Role is T;

        /// <summary>获取玩家的指定类型角色实例（如果存在）</summary>
        public static T GetRole<T>(this Game.Player player) where T : RuntimeRole
            => player.Role as T;

        /// <summary>检查玩家是否为指定角色定义</summary>
        public static bool Is<TDef, TRuntime>(this Game.Player player)
            where TDef : DefinedRole
            where TRuntime : RuntimeRole
            => player.Role is TRuntime && player.Role?.Definition is TDef;

        /// <summary>检查玩家是否为指定类别</summary>
        public static bool IsCategory(this Game.Player player, RoleCategory category)
            => player.Role?.Definition?.Category == category;

        /// <summary>检查玩家是否为船员</summary>
        public static bool IsCrewmate(this Game.Player player)
            => player.IsCategory(RoleCategory.Crewmate);

        /// <summary>检查玩家是否为内鬼</summary>
        public static bool IsImpostor(this Game.Player player)
            => player.IsCategory(RoleCategory.Impostor);

        /// <summary>检查玩家是否为中立</summary>
        public static bool IsNeutral(this Game.Player player)
            => player.IsCategory(RoleCategory.Neutral);

        /// <summary>检查玩家是否存活且有角色</summary>
        public static bool IsAliveWithRole(this Game.Player player)
            => !player.IsDead && player.HasRole;
    }
}

using System.Collections.Generic;
using LightInDark.Ability;
using LightInDark.Core;
using LightInDark.Events;
using LightInDark.Game;
using TMPro;
using UnityEngine;
using Object = UnityEngine.Object;

namespace LightInDark.Roles
{
    /// <summary>
    /// 角色运行时实例，绑定到 Player。
    /// 角色名+任务数显示在玩家名字上方的 Info 子对象中。
    /// </summary>
    public abstract class RuntimeRole : IBindPlayer, IGameOperator, ILifespan
    {
        public DefinedRole Definition { get; }
        public Player MyPlayer { get; }
        public bool AmOwner => MyPlayer.AmOwner;

        protected List<IPlayerAbility> Abilities { get; } = new();

        public bool IsDeadObject => MyPlayer.IsDeadObject;

        private TextMeshPro? _infoText;

        protected RuntimeRole(DefinedRole definition, Player player, int[] arguments)
        {
            Definition = definition;
            MyPlayer = player;
            Arguments = arguments ?? System.Array.Empty<int>();
            this.Register(player);
            EventSystem.RegisterInstance(this);

            try { OnActivated(); }
            catch (System.Exception ex) { LightLogger.LogWarning($"[RuntimeRole] OnActivated 失败: {ex.Message}"); }

            try { UpdateNameDisplay(); }
            catch (System.Exception ex) { LightLogger.LogWarning($"[RuntimeRole] UpdateNameDisplay 失败: {ex.Message}"); }
        }

        /// <summary>实例化参数（来自分配机或默认参数）</summary>
        public int[] Arguments { get; }

        protected virtual void OnActivated() { }

        /// <summary>换职时清理逻辑入口（子类覆写）</summary>
        protected virtual void OnInactivated() { }

        /// <summary>使角色失活（换职/移除时调用）</summary>
        public void Inactivate()
        {
            try { OnInactivated(); }
            catch (System.Exception ex) { LightLogger.LogWarning($"[RuntimeRole] OnInactivated 失败: {ex.Message}"); }
            Release();
        }

        protected void AddAbility(IPlayerAbility ability)
        {
            Abilities.Add(ability);
            ability.Register(this);
        }

        public IEnumerable<IPlayerAbility> GetAbilities() => Abilities;

        /// <summary>
        /// 更新玩家名字显示。
        /// - 名字颜色 = 角色颜色（仅自己）/ 白色（他人）
        /// - 名字上方创建 Info 子文本，显示：角色名 (已完成/总任务)
        /// </summary>
        public void UpdateNameDisplay()
        {
            var control = MyPlayer?.Control;
            if (control == null) return;
            if (control.cosmetics == null) return;
            if (control.cosmetics.nameText == null) return;

            try
            {
                // 名字颜色 = 角色颜色
                control.cosmetics.nameText.color = AmOwner
                    ? Definition.Color.ToUnityColor()
                    : UnityEngine.Color.white;

                // 创建/获取 Info 子文本（显示在名字上方）
                if (_infoText == null)
                {
                    var nameText = control.cosmetics.nameText;
                    _infoText = Object.Instantiate(nameText, nameText.transform);
                    _infoText.gameObject.name = "Info";
                    _infoText.fontSize = nameText.fontSize * 0.75f;
                    // 放在名字上方，稍微靠近
                    _infoText.transform.localPosition = new Vector3(0f, 0.15f, 0f);
                    _infoText.alignment = TextAlignmentOptions.Bottom;
                    _infoText.enableWordWrapping = false;
                    _infoText.raycastTarget = false;
                }

                // 构建 Info 文本
                string roleColorHex = ColorToHex(Definition.Color);
                string roleStr = $"<color=#{roleColorHex}>{Definition.Name}</color>";

                string taskStr = "";
                if (control.Data?.Tasks != null && control.Data.Tasks.Count > 0)
                {
                    int completed = 0;
                    int total = control.Data.Tasks.Count;
                    foreach (var task in control.Data.Tasks)
                    {
                        if (task != null && task.Complete) completed++;
                    }
                    taskStr = $" <color=#FAD934FF>({completed}/{total})</color>";
                }

                if (AmOwner)
                {
                    _infoText.text = $"{roleStr}{taskStr}";
                    _infoText.gameObject.SetActive(true);
                }
                else
                {
                    _infoText.text = "";
                    _infoText.gameObject.SetActive(false);
                }
            }
            catch { }
        }

        private static string ColorToHex(Color color)
        {
            byte r = (byte)(color.R * 255f);
            byte g = (byte)(color.G * 255f);
            byte b = (byte)(color.B * 255f);
            byte a = (byte)(color.A * 255f);
            return $"{r:X2}{g:X2}{b:X2}{a:X2}";
        }

        /// <summary>
        /// 任务完成事件监听。更新名字显示中的任务计数。
        /// </summary>
        [EventPriority(0)]
        void OnTaskComplete(PlayerTaskCompleteEvent ev)
        {
            if (ev.Player == MyPlayer.Control)
            {
                UpdateNameDisplay();
            }
        }

        public void Release()
        {
            EventSystem.UnregisterInstance(this);
            foreach (var ability in Abilities)
                ability.Release();
            Abilities.Clear();

            try
            {
                if (MyPlayer?.Control?.cosmetics?.nameText != null)
                    MyPlayer.Control.cosmetics.nameText.color = UnityEngine.Color.white;
            }
            catch { }

            if (_infoText != null)
            {
                try { Object.Destroy(_infoText.gameObject); } catch { }
                _infoText = null;
            }
        }

        void IGameOperator.OnReleased() { }
    }
}

using System;
using System.Collections.Generic;
using System.Reflection;
using HarmonyLib;
using Hazel;
using InnerNet;
using LightInDark.Core;
using UnityEngine;

namespace LightInDark.RPCs
{
    // =====================================================================
    // 自定义 RPC 系统
    //
    // 使用 callId = byte.MaxValue (255)
    // 通过 Harmony patch 在 InnerNetObject.HandleRpc 层面拦截
    // 发送时同时执行本地逻辑
    // =====================================================================

    /// <summary>
    /// 自定义 RPC 管理器。
    /// callId = 255 (byte.MaxValue)。
    /// </summary>
    public static class CustomRPC
    {
        /// <summary>自定义 RPC 的 callId（使用 255）</summary>
        public const byte RpcCallId = byte.MaxValue;

        private static readonly Dictionary<int, Action<MessageReader>> _handlers = new();

        public static void Register(string hash, Action<MessageReader> handler)
        {
            _handlers[hash.ComputeConstantHash()] = handler;
            LightLogger.Log($"[CustomRPC] 注册: {hash} (hash={hash.ComputeConstantHash()})");
        }

        /// <summary>
        /// 发送 RPC 到所有客户端，并在本地立即执行。
        /// </summary>
        public static void Send(string hash, Action<MessageWriter> writer, bool reliable = true)
        {
            var client = AmongUsClient.Instance;
            if (client == null) return;

            var player = PlayerControl.LocalPlayer;
            if (player == null) return;

            int hashValue = hash.ComputeConstantHash();

            // 网络发送
            if (client.AmClient && client.GameState == InnerNetClient.GameStates.Started)
            {
                try
                {
                    var msgWriter = client.StartRpcImmediately(
                        player.NetId, RpcCallId,
                        reliable ? SendOption.Reliable : SendOption.None, -1);

                    msgWriter.Write(hashValue);
                    writer?.Invoke(msgWriter);

                    client.FinishRpcImmediately(msgWriter);
                }
                catch (Exception ex)
                {
                    LightLogger.LogWarning($"[CustomRPC] 发送失败: {hash}: {ex.Message}");
                }
            }

            // 本地执行
            // 在发送端也执行方法体
            // 不需要序列化/反序列化——直接用一个单独的 Action 调用
            // handler 接收 MessageReader，但我们无法轻松地本地构造它
            // 所以：LocalExecute 由 [LidRPC] 的 Prefix 处理（直接 Invoke 方法）
            // 这里只负责网络发送
            // LidRPC.Prefix 已经处理了本地执行
        }

        /// <summary>
        /// 发送 RPC 到指定玩家（不本地执行）
        /// </summary>
        public static void SendTo(PlayerControl target, string hash, Action<MessageWriter> writer, bool reliable = true)
        {
            var client = AmongUsClient.Instance;
            if (client == null) return;

            var player = PlayerControl.LocalPlayer;
            if (player == null) return;

            int hashValue = hash.ComputeConstantHash();

            try
            {
                var msgWriter = client.StartRpcImmediately(
                    player.NetId, RpcCallId,
                    reliable ? SendOption.Reliable : SendOption.None,
                    target.OwnerId);

                msgWriter.Write(hashValue);
                writer?.Invoke(msgWriter);

                client.FinishRpcImmediately(msgWriter);
            }
            catch (Exception ex)
            {
                LightLogger.LogWarning($"[CustomRPC] SendTo 失败: {hash}: {ex.Message}");
            }
        }

        /// <summary>
        /// 仅发送 RPC（不本地执行）
        /// </summary>
        public static void SendOnly(string hash, Action<MessageWriter> writer, bool reliable = true)
        {
            var client = AmongUsClient.Instance;
            if (client == null || !client.AmClient) return;

            var player = PlayerControl.LocalPlayer;
            if (player == null) return;

            int hashValue = hash.ComputeConstantHash();

            try
            {
                var msgWriter = client.StartRpcImmediately(
                    player.NetId, RpcCallId,
                    reliable ? SendOption.Reliable : SendOption.None, -1);

                msgWriter.Write(hashValue);
                writer?.Invoke(msgWriter);

                client.FinishRpcImmediately(msgWriter);
            }
            catch (Exception ex)
            {
                LightLogger.LogWarning($"[CustomRPC] SendOnly 失败: {hash}: {ex.Message}");
            }
        }

        /// <summary>
        /// 处理收到的自定义 RPC。
        /// 从 reader 读取 hash，查找 handler，执行。
        /// </summary>
        internal static void HandleRpc(MessageReader reader)
        {
            try
            {
                int hash = reader.ReadInt32();
                if (_handlers.TryGetValue(hash, out var handler))
                {
                    handler.Invoke(reader);
                }
                else
                {
                    LightLogger.LogWarning($"[CustomRPC] 未知 RPC hash: {hash}");
                }
            }
            catch (Exception ex)
            {
                LightLogger.LogWarning($"[CustomRPC] 处理失败: {ex.Message}\n{ex.StackTrace}");
            }
        }
    }

    // =====================================================================
    // Harmony Patch — 在 InnerNetObject 层面拦截 HandleRpc
    // =====================================================================

    /// <summary>
    /// 拦截所有 InnerNetObject 的 HandleRpc。
    /// </summary>
    [HarmonyPatch(typeof(InnerNetObject), nameof(InnerNetObject.HandleRpc))]
    public static class CustomRpcHandlePatch
    {
        public static bool Prefix(InnerNetObject __instance, byte callId, MessageReader reader)
        {
            if (callId != CustomRPC.RpcCallId) return true; // 不是我们的 RPC，正常处理

            CustomRPC.HandleRpc(reader);
            return false; // 阻止原版处理
        }
    }

    // =====================================================================
    // 扩展方法
    // =====================================================================

    public static class MessageWriterExtensions
    {
        public static void WritePlayer(this MessageWriter writer, PlayerControl player)
            => writer.Write(player?.PlayerId ?? byte.MaxValue);

        public static void WriteVector2(this MessageWriter writer, Vector2 value)
        {
            writer.Write(value.x);
            writer.Write(value.y);
        }

        public static void WriteVector3(this MessageWriter writer, Vector3 value)
        {
            writer.Write(value.x);
            writer.Write(value.y);
            writer.Write(value.z);
        }
    }

    public static class MessageReaderExtensions
    {
        public static PlayerControl ReadPlayer(this MessageReader reader)
        {
            byte playerId = reader.ReadByte();
            if (playerId == byte.MaxValue) return null;
            foreach (var pc in PlayerControl.AllPlayerControls)
                if (pc.PlayerId == playerId) return pc;
            return null;
        }

        public static Vector2 ReadVector2(this MessageReader reader)
            => new(reader.ReadSingle(), reader.ReadSingle());

        public static Vector3 ReadVector3(this MessageReader reader)
            => new(reader.ReadSingle(), reader.ReadSingle(), reader.ReadSingle());
    }

    internal static class HashHelper
    {
        public static int ComputeConstantHash(this string str)
        {
            int hash = 0;
            foreach (char c in str)
                hash = (hash * 31) + c;
            return hash;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Reflection;
using HarmonyLib;
using Hazel;
using LightInDark.Core;
using UnityEngine;

namespace LightInDark.RPCs
{
    /// <summary>标记一个静态方法为 RPC。定义即用。</summary>
    [AttributeUsage(AttributeTargets.Method)]
    public class LidRPCAttribute : Attribute
    {
        public bool OnlyHost { get; set; } = false;
        public bool Reliable { get; set; } = true;
        /// <summary>是否在发送端本地执行（默认 true）</summary>
        public bool LocalExecute { get; set; } = true;
    }

    /// <summary>
    /// RPC 自动注册器。
    /// 扫描 [LidRPC] 方法，
    /// Harmony Prefix 拦截调用，序列化参数发送，
    /// 同时在本地执行（Before 模式）。
    /// </summary>
    public static class LidRpcRegistry
    {
        private static bool _initialized;

        private class RpcEntry
        {
            public string HashStr;
            public int Hash;
            public MethodInfo Method;
            public ParameterInfo[] Parameters;
            public bool OnlyHost;
            public bool Reliable;
            public bool LocalExecute;
        }

        private static readonly Dictionary<int, RpcEntry> _entries = new();

        public static void ScanAndPatch(Harmony harmony)
        {
            if (_initialized) return;
            _initialized = true;

            var assembly = Assembly.GetExecutingAssembly();

            foreach (var type in assembly.GetTypes())
            {
                foreach (var method in type.GetMethods(
                    BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static))
                {
                    var attr = method.GetCustomAttribute<LidRPCAttribute>();
                    if (attr == null) continue;

                    var hashStr = $"{type.FullName}.{method.Name}";
                    var hash = hashStr.ComputeConstantHash();

                    var entry = new RpcEntry
                    {
                        HashStr = hashStr,
                        Hash = hash,
                        Method = method,
                        Parameters = method.GetParameters(),
                        OnlyHost = attr.OnlyHost,
                        Reliable = attr.Reliable,
                        LocalExecute = attr.LocalExecute,
                    };
                    _entries[hash] = entry;

                    // 注册接收处理器（接收端执行）
                    var localEntry = entry;
                    CustomRPC.Register(hashStr, reader =>
                    {
                        var args = DeserializeArgs(reader, localEntry.Parameters);
                        localEntry.Method.Invoke(null, args);
                    });

                    // Harmony Prefix：拦截调用，发送 RPC
                    var prefix = new HarmonyMethod(typeof(LidRpcRegistry), nameof(RpcPrefix));
                    harmony.Patch(method, prefix: prefix);

                    LightLogger.Log($"[LidRPC] 注册: {hashStr} (hash={hash}, {entry.Parameters.Length} params, local={entry.LocalExecute})");
                }
            }

            LightLogger.Log($"[LidRPC] 扫描完成，共 {_entries.Count} 个 RPC");
        }

        // 防止无限递归的标志
        private static bool _isLocalExecuting;

        /// <summary>
        /// Harmony Prefix — 拦截 [LidRPC] 方法调用。
        /// 发送 RPC + 本地执行。
        /// </summary>
        internal static bool RpcPrefix(MethodBase __originalMethod, object[] __args)
        {
            // 本地执行中：放行，执行方法体
            if (_isLocalExecuting)
                return true;

            var hashStr = $"{__originalMethod.DeclaringType?.FullName}.{__originalMethod.Name}";
            var hash = hashStr.ComputeConstantHash();

            if (!_entries.TryGetValue(hash, out var entry))
                return true;

            // 房主检查
            if (entry.OnlyHost && !AmongUsClient.Instance.AmHost)
                return false;

            // 序列化参数用于网络发送
            var payloadWriter = MessageWriter.Get(SendOption.Reliable);
            SerializeArgs(payloadWriter, __args, entry.Parameters);
            var payloadBytes = payloadWriter.ToByteArray(false);

            // 发送到网络
            CustomRPC.SendOnly(entry.HashStr, writer =>
            {
                writer.Write(payloadBytes, 0, payloadBytes.Length);
            }, entry.Reliable);

            // 本地执行
            if (entry.LocalExecute)
            {
                try
                {
                    _isLocalExecuting = true;
                    entry.Method.Invoke(null, __args);
                }
                catch (Exception ex)
                {
                    LightLogger.LogWarning($"[LidRPC] 本地执行失败: {hashStr}: {ex.Message}");
                }
                finally
                {
                    _isLocalExecuting = false;
                }
            }

            // 跳过原方法体（发送端不重复执行）
            return false;
        }

        // ---- 序列化 ----

        private static void SerializeArgs(MessageWriter writer, object[] args, ParameterInfo[] parameters)
        {
            for (int i = 0; i < parameters.Length; i++)
            {
                SerializeArg(writer, args[i], parameters[i].ParameterType);
            }
        }

        private static void SerializeArg(MessageWriter writer, object value, Type type)
        {
            if (type == typeof(byte)) writer.Write((byte)value);
            else if (type == typeof(int)) writer.Write((int)value);
            else if (type == typeof(float)) writer.Write((float)value);
            else if (type == typeof(bool)) writer.Write((bool)value);
            else if (type == typeof(string)) writer.Write((string?)value ?? "");
            else if (type == typeof(PlayerControl)) writer.WritePlayer((PlayerControl?)value);
            else if (type == typeof(Vector2)) writer.WriteVector2((Vector2)value);
            else if (type == typeof(Vector3)) writer.WriteVector3((Vector3)value);
            else throw new NotSupportedException($"[LidRPC] 不支持的类型: {type.Name}");
        }

        private static object?[] DeserializeArgs(MessageReader reader, ParameterInfo[] parameters)
        {
            var args = new object?[parameters.Length];
            for (int i = 0; i < parameters.Length; i++)
            {
                args[i] = DeserializeArg(reader, parameters[i].ParameterType);
            }
            return args;
        }

        private static object? DeserializeArg(MessageReader reader, Type type)
        {
            if (type == typeof(byte)) return reader.ReadByte();
            if (type == typeof(int)) return reader.ReadInt32();
            if (type == typeof(float)) return reader.ReadSingle();
            if (type == typeof(bool)) return reader.ReadBoolean();
            if (type == typeof(string)) return reader.ReadString();
            if (type == typeof(PlayerControl)) return reader.ReadPlayer();
            if (type == typeof(Vector2)) return reader.ReadVector2();
            if (type == typeof(Vector3)) return reader.ReadVector3();
            throw new NotSupportedException($"[LidRPC] 不支持的类型: {type.Name}");
        }
    }
}

using LightInDark.Core;
using LightInDark.Game;
using LightInDark.Roles;
using System;
using UnityEngine;

namespace LightInDark.RPCs
{
    /// <summary>
    /// RPC 定义文件。使用 [LidRPC] 属性，定义即用。
    /// </summary>
    public static class RpcDefinitions
    {
        // ============ 角色同步 ============

        [LidRPC]
        public static void SetRole(byte playerId, int roleId, int[] arguments)
        {
            var definedRole = RoleRegistry.GetById(roleId);
            if (definedRole == null) { LightLogger.LogWarning($"[RPC] 未知角色Id: {roleId}"); return; }
            var gamePlayer = Game.GameManager.Instance.GetPlayer(playerId);
            if (gamePlayer == null) return;
            gamePlayer.SetRoleLocal(definedRole, arguments);
            Game.LightPlayerDataManager.SetRole(playerId, definedRole.Name);
        }

        // ============ 玩家操作 ============

        [LidRPC]
        public static void Suicide(PlayerControl player, bool needLog = true, string state = "suicide", PlayerState playerState = PlayerState.Suicide)
        {
            if (player == null || player.Data.IsDead) return;
            player.RpcMurderPlayer(player, true);
            Events.EventSystem.RunEvent(new Events.PlayerSuicideEvent { Player = player, Reason = state, NeedLog = needLog, State = playerState });
            LightPlayerDataManager.SetDeath(player.PlayerId, playerState, player.PlayerId, LightPlayerDataManager.CurrentMeetingNumber);
            if (needLog) LightLogger.Log($"[RPC] {player.name} suicide. state:{state}");
        }

        [LidRPC]
        public static void MurderPlayer(PlayerControl killer, PlayerControl victim, PlayerState state = PlayerState.BeKilled)
        {
            if (killer == null || victim == null) return;
            killer.RpcMurderPlayer(victim, true);
            Events.EventSystem.RunEvent(new Events.PlayerMurderEvent { Player = killer, Victim = victim, State = state });
            LightPlayerDataManager.SetDeath(victim.PlayerId, state, killer.PlayerId, LightPlayerDataManager.CurrentMeetingNumber);
        }

        /// <summary>恢复玩家（取消死亡状态）</summary>
        [LidRPC(OnlyHost = true)]
        public static void RevivePlayer(byte playerId)
        {
            foreach (var pc in PlayerControl.AllPlayerControls)
                if (pc.PlayerId == playerId && pc.Data.IsDead)
                {
                    pc.Revive();
                    Events.EventSystem.RunEvent(new Events.PlayerReviveEvent { Player = pc });
                    LightLogger.Log($"[RPC] {pc.name} 已复活");
                    break;
                }
        }

        /// <summary>设置玩家可见性</summary>
        [LidRPC]
        public static void SetPlayerInvisible(byte playerId, bool invisible)
        {
            foreach (var pc in PlayerControl.AllPlayerControls)
                if (pc.PlayerId == playerId)
                {
                    pc.SetInvisibility(invisible);
                    break;
                }
        }

        /// <summary>传送玩家到指定位置</summary>
        [LidRPC(OnlyHost = true)]
        public static void TeleportPlayer(byte playerId, Vector2 position)
        {
            foreach (var pc in PlayerControl.AllPlayerControls)
                if (pc.PlayerId == playerId)
                {
                    var pos = new UnityEngine.Vector3(position.x, position.y, pc.transform.position.z);
                    pc.NetTransform.SnapTo(pos);
                    LightLogger.Log($"[RPC] {pc.name} 传送到 {position}");
                    break;
                }
        }

        // ============ 会议 ============

        [LidRPC]
        public static void StartMeeting(byte reporterId, byte reportedId)
        {
            if (MeetingHud.Instance != null) return;
            PlayerControl reporter = null;
            foreach (var pc in PlayerControl.AllPlayerControls)
                if (pc.PlayerId == reporterId) { reporter = pc; break; }

            if (reporter == null) return;

