        if (pc == null) return null;
        return Game.GameManager.Instance?.GetPlayer(pc.PlayerId);
    }


    /// <summary>
    /// 展示一个类似于断开连接的弹窗，显示自定义文本。
    /// </summary>
    /// <param name="text">要显示的文本</param>
    public static void ShowCustomDisconnectWindow(string text)
    {
